use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};

const HASHMAP_INITIAL_CAPACITY: usize = 16;

/// Entry in the hash map containing a key-value pair and pointer to next entry
struct HashMapEntry<T> {
    key: String,
    value: T,
    next: Option<Box<HashMapEntry<T>>>,
}

/// Simple hash map implementation using separate chaining
pub struct HashMap<T> {
    buckets: Vec<Option<Box<HashMapEntry<T>>>>,
    capacity: usize,
    size: usize,
}

/// Simple hash function (djb2)
fn hash_string(s: &str) -> u64 {
    let mut hash: u64 = 5381;
    for c in s.bytes() {
        hash = hash.wrapping_shl(5).wrapping_add(hash).wrapping_add(c as u64);
    }
    hash
}

impl<T> HashMap<T> {
    /// Create a new hash map
    pub fn new() -> Self {
        HashMap {
            buckets: (0..HASHMAP_INITIAL_CAPACITY).map(|_| None).collect(),
            capacity: HASHMAP_INITIAL_CAPACITY,
            size: 0,
        }
    }

    /// Insert or update a key-value pair
    pub fn put(&mut self, key: &str, value: T) -> Result<(), String> {
        let hash = hash_string(key);
        let index = (hash % self.capacity as u64) as usize;

        let mut current = &mut self.buckets[index];

        // Check if key exists and update
        loop {
            match current {
                Some(entry) => {
                    if entry.key == key {
                        entry.value = value;
                        return Ok(());
                    }
                    current = &mut entry.next;
                }
                None => break,
            }
        }

        // Create new entry
        let new_entry = Box::new(HashMapEntry {
            key: key.to_string(),
            value,
            next: self.buckets[index].take(),
        });

        self.buckets[index] = Some(new_entry);
        self.size += 1;

        Ok(())
    }

    /// Get value for a key
    pub fn get(&self, key: &str) -> Option<&T> {
        let hash = hash_string(key);
        let index = (hash % self.capacity as u64) as usize;

        let mut current = &self.buckets[index];

        while let Some(entry) = current {
            if entry.key == key {
                return Some(&entry.value);
            }
            current = &entry.next;
        }

        None
    }

    /// Get mutable value for a key
    pub fn get_mut(&mut self, key: &str) -> Option<&mut T> {
        let hash = hash_string(key);
        let index = (hash % self.capacity as u64) as usize;

        let mut current = &mut self.buckets[index];

        while let Some(entry) = current {
            if entry.key == key {
                return Some(&mut entry.value);
            }
            current = &mut entry.next;
        }

        None
    }

    /// Remove a key-value pair
    pub fn remove(&mut self, key: &str) -> Result<(), String> {
        let hash = hash_string(key);
        let index = (hash % self.capacity as u64) as usize;

        let mut current = &mut self.buckets[index];

        loop {
            match current {
                Some(entry) => {
                    if entry.key == key {
                        *current = entry.next.take();
                        self.size -= 1;
                        return Ok(());
                    }
                    current = &mut entry.next;
                }
                None => return Err("Key not found".to_string()),
            }
        }
    }

    /// Get the number of entries in the map
    pub fn size(&self) -> usize {
        self.size
    }

    /// Get the capacity of the map
    pub fn capacity(&self) -> usize {
        self.capacity
    }
}

impl<T> Default for HashMap<T> {
    fn default() -> Self {
        Self::new()
    }
}

