use std::collections::hash_map::DefaultHasher;
use std::error::Error;
use std::fmt;
use std::hash::{Hash, Hasher};
use std::ptr;

const HASHMAP_INITIAL_CAPACITY: usize = 16;

#[derive(Debug)]
struct HashMapError(String);

impl fmt::Display for HashMapError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "HashMapError: {}", self.0)
    }
}

impl Error for HashMapError {}

type Result<T> = std::result::Result<T, HashMapError>;

#[derive(Debug)]
struct HashMapEntry<K, V> {
    key: K,
    value: V,
    next: Option<Box<HashMapEntry<K, V>>>,
}

#[derive(Debug)]
struct HashMap<K, V> {
    buckets: Vec<Option<Box<HashMapEntry<K, V>>>>,
    capacity: usize,
    size: usize,
}

impl<K, V> HashMap<K, V>
where
    K: Eq + Hash + Clone,
{
    /// Creates a new hash map with the initial capacity.
    fn new() -> Self {
        let capacity = HASHMAP_INITIAL_CAPACITY;
        let buckets = vec![None; capacity];
        HashMap {
            buckets,
            capacity,
            size: 0,
        }
    }

    /// Generates a hash value for the given key.
    fn hash_string(key: &K) -> u64 {
        let mut hasher = DefaultHasher::new();
        key.hash(&mut hasher);
        hasher.finish()
    }

    /// Inserts a key-value pair into the hash map.
    fn put(&mut self, key: K, value: V) -> Result<()> {
        let hash = Self::hash_string(&key);
        let index = (hash % self.capacity as u64) as usize;

        match &mut self.buckets[index] {
            Some(entry) => {
                let mut current = entry;
                loop {
                    if current.key == key {
                        current.value = value;
                        return Ok(());
                    }
                    match &mut current.next {
                        Some(next_entry) => {
                            current = next_entry;
                        }
                        None => {
                            break;
                        }
                    }
                }

                let new_entry = HashMapEntry {
                    key: key.clone(),
                    value,
                    next: None,
                };
                current.next = Some(Box::new(new_entry));
            }
            None => {
                let new_entry = HashMapEntry {
                    key: key.clone(),
                    value,
                    next: None,
                };
                self.buckets[index] = Some(Box::new(new_entry));
            }
        }

        self.size += 1;
        Ok(())
    }

    /// Retrieves the value associated with the given key.
    fn get(&self, key: &K) -> Option<&V> {
        let hash = Self::hash_string(key);
        let index = (hash % self.capacity as u64) as usize;

        let mut current = self.buckets[index].as_ref()?;
        loop {
            if current.key == *key {
                return Some(&current.value);
            }
            match &current.next {
                Some(next_entry) => {
                    current = next_entry;
                }
                None => {
                    return None;
                }
            }
        }
    }

    /// Removes a key-value pair from the hash map.
    fn remove(&mut self, key: &K) -> Result<()> {
        let hash = Self::hash_string(key);
        let index = (hash % self.capacity as u64) as usize;

        match &mut self.buckets[index] {
            Some(entry) => {
                if entry.key == *key {
                    self.buckets[index] = entry.next.take();
                    self.size -= 1;
                    return Ok(());
                } else {
                    let mut current = entry;
                    while let Some(next_entry) = &mut current.next {
                        if next_entry.key == *key {
                            current.next = next_entry.next.take();
                            self.size -= 1;
                            return Ok(());
                        }
                        current = next_entry;
                    }
                }
            }
            None => {
                return Err(HashMapError("Key not found".to_string()));
            }
        }

        Err(HashMapError("Key not found".to_string()))
    }
}
